/// <summary>
///  Constructs a <c>METTransferOrderExtractionBusinessEventContract</c>.
/// </summary>
/// <param name = "_wmsPickingRoute">
/// <c>WMSPickingRoute</c> record.
/// </param>
/// <returns>An instance of <c>METTransferOrderExtractionBusinessEventContract</c>.</returns>
public static METTransferOrderExtractionBusinessEventContract newFromWMSPickingRoute(WMSPickingRoute _wmsPickingRoute)
{
    METTransferOrderExtractionBusinessEventContract contract = new METTransferOrderExtractionBusinessEventContract();
    contract.initialize(_wmsPickingRoute);
    return contract;
}

/// <summary>
/// Initializes data variables.
/// </summary>
/// <param name = "_wmsPickingRoute">
/// <c>WMSPickingRoute</c> record.
/// </param>
private void initialize(WMSPickingRoute _wmsPickingRoute)
{
    legalEntity    = curExt();
    pickingRouteId = _wmsPickingRoute.pickingRouteID;
    createdBy      = _wmsPickingRoute.CreatedBy;
}

    /// <summary>
    /// Gets and sets legal entity.
    /// </summary>
    /// <param name = "_legalEntity">Legal entity.</param>
    /// <returns>Legal entity.</returns>

    [DataMember(#LegalEntity), BusinessEventsDataMember("@ProcurementAndSourcing:LegalEntity")]
    public LegalEntityDataAreaId parmLegalEntity(LegalEntityDataAreaId _legalEntity = legalEntity)
    {
        legalEntity = _legalEntity;
        return legalEntity;
    }

/// <summary>
/// Gets and sets picking route Id.
/// </summary>
/// <param name = "_pickingRouteId"> Picking route Id.</param>
/// <returns>Picking route Id.</returns>
[DataMember(#PickingListNumber), BusinessEventsDataMember("@GLS6465")]
public WMSPickingRouteID parmWMSPickingRouteID(WMSPickingRouteID _pickingRouteId = pickingRouteId)
{
    pickingRouteId = _pickingRouteId;
    return pickingRouteId;
}

/// <summary>
/// Gets and sets created by.
/// </summary>
/// <param name = "_createdBy">Created by.</param>
/// <returns>Created by.></returns>
[DataMember(#CreatedBy), BusinessEventsDataMember("@SYS2192")]
public CreatedBy parmCreatedBy(CreatedBy _createdBy = createdBy)
{
    createdBy = _createdBy;
    return createdBy;
}
